    if (!_toBlock) {
      throw new UnknownBlockError(`Unknown block tag ${toBlock}`);
    }
    const _fromBlock = await getBlock(fromBlock ?? "latest");
    if (!_fromBlock) {
      throw new UnknownBlockError(`Unknown block tag ${fromBlock}`);
    }
